package com.medcloud.course.portal;

import com.medcloud.course.contract.Role;
import com.medcloud.course.portal.web.PaasClient;
import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.*;
import javax.servlet.http.HttpServlet;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.io.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class ClinicalSupplementPortalTest {
    static final String ID="11111111-1111-1111-1111-111111111111", KEY="22222222-2222-2222-2222-222222222222";
    HttpServer server; HttpServlet servlet; List<String> calls=new ArrayList<>(); String body; int status=200;
    @BeforeEach void start() throws Exception {
        server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
        server.createContext("/api",x->{calls.add(x.getRequestMethod()+" "+x.getRequestURI());body=new String(read(x.getRequestBody()),StandardCharsets.UTF_8);
            String data=x.getRequestURI().getPath().endsWith("/context")?"{\"id\":\""+ID+"\",\"name\":\"医院\",\"status\":\"ACTIVE\",\"businessWritable\":true}":"{}";
            byte[] bytes=("{\"code\":\"OK\",\"data\":"+data+"}").getBytes(StandardCharsets.UTF_8);x.sendResponseHeaders(status,bytes.length);x.getResponseBody().write(bytes);x.close();});server.start();
        servlet=(HttpServlet)Class.forName("com.medcloud.course.portal.web.ClinicalSupplementServlet").getConstructor(PaasClient.class).newInstance(new PaasClient("http://127.0.0.1:"+server.getAddress().getPort()+"/api"));
    }
    @AfterEach void stop(){if(server!=null)server.stop(0);}
    static byte[] read(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}
    MockHttpServletRequest request(String path,Role role){MockHttpServletRequest r=new MockHttpServletRequest("POST",path);r.setServletPath(path);r.setContextPath("/portal");MockHttpSession s=new MockHttpSession();s.setAttribute("role",role);s.setAttribute("csrfToken","csrf");s.setAttribute("accessToken","trusted");r.setSession(s);r.addParameter("csrfToken","csrf");r.addParameter("appointmentId",ID);r.addParameter("recordId",ID);r.addParameter("expectedRevision","0");r.addParameter("operationKey",KEY);r.addParameter("complaint","患者私密😀<script>x</script>");r.addParameter("diagnosis","诊断");r.addParameter("advice","建议\n休息");r.addParameter("notes","");r.addParameter("reason","更正原因");return r;}
    @Test void roleAndCsrfBeforeApiWrite()throws Exception{for(Role role:new Role[]{Role.PATIENT,Role.HOSPITAL_ADMIN,Role.PLATFORM_ADMIN}){MockHttpServletResponse s=new MockHttpServletResponse();servlet.service(request("/doctor/clinical/save",role),s);assertEquals(403,s.getStatus());}MockHttpServletRequest r=request("/doctor/clinical/save",Role.DOCTOR);r.setParameter("csrfToken","wrong");MockHttpServletResponse s=new MockHttpServletResponse();servlet.service(r,s);assertEquals(403,s.getStatus());assertTrue(calls.isEmpty());}
    @Test void noJsDraftSaveAndCompletePrg()throws Exception{for(String action:new String[]{"save","complete"}){MockHttpServletRequest r=request("/doctor/clinical/"+action,Role.DOCTOR);MockHttpServletResponse s=new MockHttpServletResponse();servlet.service(r,s);assertEquals(303,s.getStatus());assertTrue(calls.contains((action.equals("save")?"PUT":"POST")+" /api/doctor/appointments/"+ID+(action.equals("save")?"/draft":"/complete")));assertTrue(body.contains("诊断"));assertTrue(body.contains(action.equals("save")?"expectedRevision":"expectedDraftRevision"));assertFalse(s.getHeader("Location").contains("私密"));assertFalse(Collections.list(r.getSession().getAttributeNames()).contains("flash"));}}
    @Test void versionConflictKeepsRequestInputNotFlash()throws Exception{status=409;MockHttpServletRequest r=request("/doctor/clinical/save",Role.DOCTOR);MockHttpServletResponse s=new MockHttpServletResponse();servlet.service(r,s);assertEquals(409,s.getStatus());assertEquals("/WEB-INF/views/clinical-workspace.jsp",s.getForwardedUrl());assertEquals("患者私密😀<script>x</script>",r.getAttribute("complaint"));assertNull(r.getSession().getAttribute("flash"));assertNull(s.getRedirectedUrl());}
    @Test void correctionRetryKeepsOperationKey()throws Exception{status=409;MockHttpServletRequest r=request("/doctor/correction/append",Role.DOCTOR);MockHttpServletResponse s=new MockHttpServletResponse();servlet.service(r,s);assertEquals(KEY,r.getAttribute("operationKey"));assertEquals("0",r.getAttribute("expectedRevision"));assertTrue(body.contains(KEY));assertNull(r.getSession().getAttribute("operationKey"));}
    @Test void forbiddenWritesRetainOnlyCurrentRequestAndDoNotReloadBackend()throws Exception{status=403;for(String path:new String[]{"/patient/complaint/save","/doctor/clinical/save","/doctor/clinical/complete","/doctor/correction/append"}){calls.clear();MockHttpServletRequest r=request(path,path.startsWith("/patient/")?Role.PATIENT:Role.DOCTOR);r.addParameter("description","自述私密");MockHttpServletResponse s=new MockHttpServletResponse();servlet.service(r,s);assertEquals(403,s.getStatus());assertEquals(false,r.getAttribute("clinicalWritable"));assertEquals("0",r.getAttribute("expectedRevision"));assertEquals(KEY,r.getAttribute("operationKey"));assertEquals("患者私密😀<script>x</script>",r.getAttribute("complaint"));assertEquals("自述私密",r.getAttribute("description"));assertEquals(1,calls.size());assertNull(s.getHeader("Location"));assertEquals("no-store",s.getHeader("Cache-Control"));for(String key:Collections.list(r.getSession().getAttributeNames()))assertFalse(String.valueOf(r.getSession().getAttribute(key)).contains("私密"));}}
    @Test void unauthorizedWriteStillInvalidatesSessionAndReturnsToLogin()throws Exception{status=401;MockHttpServletRequest r=request("/doctor/correction/append",Role.DOCTOR);MockHttpSession session=(MockHttpSession)r.getSession();MockHttpServletResponse s=new MockHttpServletResponse();servlet.service(r,s);assertTrue(session.isInvalid());assertEquals("/portal/login",s.getRedirectedUrl());assertNull(s.getForwardedUrl());assertFalse(s.getContentAsString().contains("私密"));assertEquals(1,calls.size());}
    @Test void browserCannotSelectBackendOrInjectTargetPath()throws Exception{for(String id:new String[]{"../doctor","?token=x",ID+"/draft",ID+"%2fcomplete",ID+"#fragment"}){MockHttpServletRequest r=request("/patient/complaint/save",Role.PATIENT);r.setParameter("appointmentId",id);MockHttpServletResponse s=new MockHttpServletResponse();servlet.service(r,s);assertEquals(400,s.getStatus());}assertTrue(calls.isEmpty());MockHttpServletRequest r=request("/patient/complaint/save",Role.PATIENT);r.addParameter("description","私密描述");r.addParameter("url","http://evil.example");r.addParameter("token","browser-token");r.addParameter("tenantId",KEY);MockHttpServletResponse s=new MockHttpServletResponse();servlet.service(r,s);assertEquals(303,s.getStatus());assertEquals("PUT /api/patient/appointments/"+ID+"/complaint",calls.get(0));assertFalse(body.contains("browser-token"));assertFalse(body.contains("tenantId"));assertFalse(s.getHeader("Location").contains("私密"));for(String key:Collections.list(r.getSession().getAttributeNames()))assertFalse(String.valueOf(r.getSession().getAttribute(key)).contains("私密"));}
    @Test void duplicateCsrfRejectedBeforeWrite()throws Exception{MockHttpServletRequest r=request("/doctor/clinical/save",Role.DOCTOR);r.addParameter("csrfToken","extra");MockHttpServletResponse s=new MockHttpServletResponse();servlet.service(r,s);assertEquals(403,s.getStatus());assertTrue(calls.isEmpty());}
    @Test void unicodeCodepointLimitsBeforeWrite()throws Exception{MockHttpServletRequest r=request("/doctor/clinical/save",Role.DOCTOR);r.setParameter("complaint",String.join("",Collections.nCopies(501,"😀")));MockHttpServletResponse s=new MockHttpServletResponse();servlet.service(r,s);assertEquals(400,s.getStatus());assertTrue(calls.isEmpty());r=request("/doctor/clinical/save",Role.DOCTOR);r.setParameter("complaint",String.join("",Collections.nCopies(500,"😀")));s=new MockHttpServletResponse();servlet.service(r,s);assertEquals(303,s.getStatus());}
}
